import axios from 'axios';

const API_URL = 'http://localhost:5000/api';

// Properties API calls
export const getProperties = async () => {
  try {
    const response = await axios.get(`${API_URL}/properties`);
    return response.data;
  } catch (error) {
    console.error('Error fetching properties:', error);
    throw error;
  }
};

export const getProperty = async (id) => {
  try {
    const response = await axios.get(`${API_URL}/properties/${id}`);
    return response.data;
  } catch (error) {
    console.error(`Error fetching property ${id}:`, error);
    throw error;
  }
};

export const createProperty = async (propertyData) => {
  try {
    const response = await axios.post(`${API_URL}/properties`, propertyData);
    return response.data;
  } catch (error) {
    console.error('Error creating property:', error);
    throw error;
  }
};

export const updateProperty = async (id, propertyData) => {
  try {
    const response = await axios.put(`${API_URL}/properties/${id}`, propertyData);
    return response.data;
  } catch (error) {
    console.error(`Error updating property ${id}:`, error);
    throw error;
  }
};

export const deleteProperty = async (id) => {
  try {
    const response = await axios.delete(`${API_URL}/properties/${id}`);
    return response.data;
  } catch (error) {
    console.error(`Error deleting property ${id}:`, error);
    throw error;
  }
};

export const searchProperties = async (params) => {
  try {
    const response = await axios.get(`${API_URL}/search/properties`, { params });
    return response.data;
  } catch (error) {
    console.error('Error searching properties:', error);
    throw error;
  }
};

// Leasing Offices API calls
export const getOffices = async () => {
  try {
    const response = await axios.get(`${API_URL}/offices`);
    return response.data;
  } catch (error) {
    console.error('Error fetching offices:', error);
    throw error;
  }
};
